    "व्यक्तीनुसार अधिकारांची मुदत {n} दिवसांत संपते — गरज असल्यास वाढवा." => ["व्यक्तिगत अधिकारों की अवधि {n} दिनों में समाप्त होगी — ज़रूरत हो तो बढ़ाएँ।", "Person-wise permissions expire within {n} days — extend if needed."],
