    "व्यक्तींना संवेदनशील अधिकार कायमचे (मुदतीशिवाय) दिले आहेत — मुदत ठेवणं सुरक्षित." => ["व्यक्तियों को संवेदनशील अधिकार स्थायी (बिना अवधि) दिए गए हैं — अवधि रखना सुरक्षित है।", "people have sensitive permissions permanently (no expiry) — setting an expiry is safer."],
