    "कोणाला कोणता" => ["किसे कौन-सा", "who gets which"],
    "मूळ Modules (कामकाज, Tasks, पत्रव्यवहार, विनंत्या, हजेरी, संदेश, तक्रार) सगळ्यांना नेहमी. खालचे फक्त अधिकार / विभाग असेल तर." => ["मूल Modules (कामकाज, Tasks, पत्राचार, अनुरोध, हाज़िरी, संदेश, शिकायत) सभी को हमेशा। नीचे वाले केवल अधिकार / विभाग होने पर।", "Core modules (work, Tasks, letters, requests, attendance, messages, grievances) are always available to everyone. The ones below only with a permission / department."],
    "या विभागाचे सगळे कर्मचारी" => ["इस विभाग के सभी कर्मचारी", "All staff of this department"],
