    "पद न बदलता एका व्यक्तीपुरते — मुदत संपल्यावर आपोआप बंद" => ["पद बदले बिना केवल एक व्यक्ति के लिए — अवधि समाप्त होने पर अपने-आप बंद", "For one person without changing the role — turns off automatically on expiry"],
    "व्यक्तीला Access द्या" => ["व्यक्ति को Access दें", "Give access to a person"],
    "अजून कोणालाही व्यक्तीनुसार अधिकार दिलेले नाहीत. उदा. HOD रजेवर असताना त्यांचं काम पाहणाऱ्याला तात्पुरता अधिकार द्या." => ["अभी तक किसी को व्यक्तिगत अधिकार नहीं दिए गए। उदा. HOD छुट्टी पर हों तो उनका काम देखने वाले को अस्थायी अधिकार दें।", "No person-wise permissions yet. E.g. give temporary access to whoever covers for an HOD on leave."],
