    "बदल जतन झाले — लगेच लागू." => ["बदलाव सहेजे गए — तुरंत लागू।", "changes saved — applied immediately."],
    "काहीही बदल नाही." => ["कोई बदलाव नहीं।", "No changes."],
    "पद न बदलता एका व्यक्तीला जास्तीचा अधिकार द्या, किंवा पदाचा एखादा अधिकार फक्त त्या व्यक्तीसाठी काढा — हवं तर ठराविक तारखेपर्यंत (उदा. रजेवरच्या HOD चं काम सांभाळणाऱ्यासाठी)." => ["पद बदले बिना किसी व्यक्ति को अतिरिक्त अधिकार दें, या पद का कोई अधिकार केवल उस व्यक्ति के लिए हटाएँ — चाहें तो किसी तारीख तक (उदा. छुट्टी पर गए HOD का काम संभालने वाले के लिए)।", "Give a person an extra permission without changing their role, or revoke a role permission just for them — optionally until a date (e.g. for someone covering an HOD on leave)."],
    "व्यक्तीनुसार अधिकारांसाठी Database Update बाकी आहे" => ["व्यक्तिगत अधिकारों के लिए Database Update बाकी है", "Database Update is pending for person-wise permissions"],
