    "ने कळवलं (किंवा त्या PIN चा पहिला Punch आला) की कर्मचारी आपोआप" => ["ने बताया (या उस PIN का पहला Punch आया) तो कर्मचारी अपने आप", "reports it (or the first punch of that PIN arrives), the staff automatically moves to"],
