    "च्या पटीत द्या (उदा. {n}, {n}, {n})." => ["के गुणकों में दें (जैसे {n}, {n}, {n})।", "in multiples of (e.g. {n}, {n}, {n})."],
    "दोन Campus ना दिली आहे — प्रत्येकाला वेगळी द्या." => ["दो Campus को दी है — हर एक को अलग दें।", "is given to two campuses — give each a different one."],
    "जतन झाल्या — नवीन कर्मचाऱ्यांना आता या Series मधले PIN मिळतील (आधीचे PIN बदलत नाहीत)." => ["सहेजी गईं — नए कर्मचारियों को अब इस Series के PIN मिलेंगे (पुराने PIN नहीं बदलते)।", "saved — new staff will now get PINs from these series (existing PINs unchanged)."],
    "कर्मचाऱ्यांना त्यांच्या Campus च्या Series मधला PIN दिला" => ["कर्मचारियों को उनके Campus की Series का PIN दिया", "staff given PINs from their campus series"],
    "व त्यांच्या Campus च्या Machine(s) वर पाठवला — आता Machine वर बोट/चेहरा नोंदवा." => ["व उनके Campus की Machine(s) पर भेजा — अब Machine पर उँगली/चेहरा दर्ज करें।", "and sent to their campus machine(s) — now enrol finger/face on the machine."],
    "त्यांच्या Campus ची Machine मंजूर झाल्यावर" => ["उनके Campus की Machine मंजूर होने पर", "after their campus machine is approved"],
    "प्रत्येक Campus ला वेगळे नंबर — PIN पाहताच कळतं कोणत्या संस्थेचा; Machine वर फक्त त्याच Campus चे कर्मचारी व त्यांचीच हजेरी" => ["हर Campus के अलग नंबर — PIN देखते ही पता चलता है किस संस्था का; Machine पर केवल उसी Campus के कर्मचारी व उन्हीं की उपस्थिति", "Separate numbers per campus — the PIN shows which institution; each machine holds and counts only its own campus staff"],
    "दुसऱ्या Campus च्या Machine वर — हजेरीत नाहीत" => ["दूसरे Campus की Machine पर — उपस्थिति में नहीं", "on another campus machine — not counted"],
    "प्रत्येकाला त्याच्या Campus च्या Series मधला पुढचा PIN, व त्याच Campus च्या Machine वर नाव; मग Machine वर बोट/चेहरा नोंदवा" => ["हर एक को उसके Campus की Series का अगला PIN, व उसी Campus की Machine पर नाम; फिर Machine पर उँगली/चेहरा दर्ज करें", "Each gets the next PIN of their campus series and is sent to that campus machine; then enrol finger/face"],
    "वर फक्त त्याच Campus चे कर्मचारी जातात आणि त्याच Campus च्या कर्मचाऱ्यांचे Punches हजेरीत धरले जातात." => ["पर केवल उसी Campus के कर्मचारी जाते हैं और उसी Campus के कर्मचारियों के Punches गिने जाते हैं।", "holds only that campus's staff and counts only their punches."],
    "दुसऱ्या Campus चा — हजेरीत नाही)" => ["दूसरे Campus का — उपस्थिति में नहीं)", "other campus — not counted)"],
    "च्या Series मधला पुढचा नंबर" => ["की Series का अगला नंबर", "next number in the series"],
