    "पत्ता / Port अवैध — सार्वजनिक IP किंवा Domain व {n}–{n} Port द्या (उदा. {n} : {n})." => ["पता / Port अमान्य — सार्वजनिक IP या Domain व {n}–{n} Port दें (जैसे {n} : {n})।", "Invalid address / port — give a public IP or domain and port {n}–{n} (e.g. {n} : {n})."],
