    "मधून कधी, कोणाला, कोणता Email गेला आणि तो Server ने स्वीकारला की नाही. (Email चा मजकूर साठवला जात नाही; OTP/पासवर्ड लपवलेले.)" => ["से कब, किसे, कौन सा Email गया और Server ने उसे स्वीकार किया या नहीं। (Email की सामग्री सहेजी नहीं जाती; OTP/पासवर्ड छिपाए गए।)", "— when, to whom and which email was sent, and whether the server accepted it. (Email content is not stored; OTPs/passwords are masked.)"],
    "म्हणजे Hosting च्या Mail Server ने Email स्वीकारला. Spam मध्ये गेला की नाही हे Server सांगू शकत नाही. नोंद {n} वर्ष ठेवली जाते." => ["का अर्थ है Hosting के Mail Server ने Email स्वीकार किया। Spam में गया या नहीं, यह Server नहीं बता सकता। रिकॉर्ड {n} वर्ष रखा जाता है।", "means the hosting mail server accepted the email. The server cannot tell whether it landed in spam. Logs are kept for {n} year."],
    "या कालावधीत कोणताही Email नोंदलेला नाही." => ["इस अवधि में कोई Email दर्ज नहीं है।", "No emails recorded in this period."],
